const fs = require("fs");
const path = require("path");

const OUT_FE = (g) => path.resolve(__dirname, "..", "public", "data", "words", g, "words_001.json");
const OUT_BE = (g) => path.resolve(__dirname, "..", "..", "..", "Services", "EnglishWordADayService", "data", "words", g, "words_001.json");

function write(genre, words) {
  for (const p of [OUT_FE(genre), OUT_BE(genre)]) {
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, JSON.stringify(words, null, 2));
  }
  console.log(`${genre}: ${words.length} words written`);
}
function d(i) { const x = new Date("2025-12-01"); x.setDate(x.getDate() + i); return x.toISOString().split("T")[0]; }
function r(a) { return a[Math.floor(Math.random() * a.length)]; }
function rats() { return Array.from({ length: r([2,3]) }, () => r([2,3,4,5])); }
function mk(genre, prefix, raw) {
  return raw.map(([word, meaning, pron, pos, diff, alts], i) => ({
    id: `${prefix}-${String(i+1).padStart(3,"0")}`,
    word, meaning, genre, difficulty: diff, dateAdded: d(i),
    samplePhrase: `${pos==="verb"?`We should ${word.toLowerCase()}`:`The ${word.toLowerCase()} aspect of`} ${["the project","this quarter","our team","the discussion","the review","this initiative"][i%6]} ${pos==="verb"?"to drive better outcomes":"helps us achieve professional excellence"}.`,
    itContext: `${word} is valuable vocabulary for IT professionals in ${genre.replace(/-/g," ")} contexts.`,
    alternativeWords: alts, pronunciation: pron, partOfSpeech: pos, ratings: rats(),
  }));
}

